/* Lightweight input normalization; RouterOS usernames must keep their characters. */
(function () {
    function clean(value, removeSpaces, numerals) {
        value = String(value || '');
        if (removeSpaces) value = value.replace(/[\s\u200b-\u200d\ufeff]/g, '');
        if (numerals) value = value.replace(/[٠-٩]/g, function (d) { return String(d.charCodeAt(0) - 1632); })
            .replace(/[۰-۹]/g, function (d) { return String(d.charCodeAt(0) - 1776); });
        return value;
    }
    function init() {
        var fields = document.querySelectorAll('input[improve-input]');
        for (var i = 0; i < fields.length; i++) {
            fields[i].addEventListener('input', function () {
                this.value = clean(this.value, this.hasAttribute('rm-white-spaces'), this.hasAttribute('to-arabic-numbers'));
            });
        }
    }
    document.addEventListener('DOMContentLoaded', init, false);
})();
